      if (Math.random() < 0.15) fx.burst("sparkle", P.x, P.y + 0.2, -0.3, 1, 0.5);
    } else if (balloon) {
      P.vy = damp(P.vy, C.balloonV + Math.sin(P.t * 2) * 0.6, 3, dt);
